create extension if not exists pgcrypto;
create table if not exists public.services(id uuid primary key default gen_random_uuid(),name text not null,description text not null default '',duration_minutes integer not null default 30 check(duration_minutes>0),price_idr integer not null default 0 check(price_idr>=0),active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now());
alter table public.services add column if not exists image_url text;
alter table public.services add column if not exists storage_path text;
create table if not exists public.professionals(id uuid primary key default gen_random_uuid(),name text not null,title text not null default 'Professional Barber',bio text not null default '',image_url text,storage_path text,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),booking_code text not null unique default('GF-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),customer_name text not null,customer_phone text not null,service_id uuid references public.services(id) on delete set null,service_name text not null,service_price_idr integer not null default 0,barber_name text not null default 'Barber tersedia',booking_date date not null,booking_time time not null,notes text not null default '',status text not null default 'pending' check(status in('pending','confirmed','completed','cancelled')),created_at timestamptz not null default now());
create table if not exists public.gallery_photos(id uuid primary key default gen_random_uuid(),title text not null default '',image_url text not null,storage_path text,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.shop_settings(id integer primary key default 1 check(id=1),shop_name text not null default 'GOODFELLAS',address text not null default 'Cirebon, Jawa Barat',phone text not null default '',instagram_url text not null default 'https://www.instagram.com/goodfellas_cirebon/',opening_time time not null default '10:00',closing_time time not null default '21:00',slot_minutes integer not null default 30 check(slot_minutes in(15,20,30,40,60)),updated_at timestamptz not null default now());
create or replace function public.is_goodfellas_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
alter table public.services enable row level security;alter table public.professionals enable row level security;alter table public.admin_users enable row level security;alter table public.bookings enable row level security;alter table public.gallery_photos enable row level security;alter table public.shop_settings enable row level security;
drop policy if exists "Public can view active services" on public.services;create policy "Public can view active services" on public.services for select using(active=true or public.is_goodfellas_admin());
drop policy if exists "Admins manage services" on public.services;create policy "Admins manage services" on public.services for all to authenticated using(public.is_goodfellas_admin()) with check(public.is_goodfellas_admin());
drop policy if exists "Admins can view admin list" on public.admin_users;create policy "Admins can view admin list" on public.admin_users for select to authenticated using(public.is_goodfellas_admin());
drop policy if exists "Customers can create bookings" on public.bookings;create policy "Customers can create bookings" on public.bookings for insert to anon,authenticated with check(length(trim(customer_name)) between 2 and 100 and length(regexp_replace(customer_phone,'[^0-9+]','','g')) between 8 and 20 and booking_date>=current_date and status='pending');
drop policy if exists "Admins can view bookings" on public.bookings;create policy "Admins can view bookings" on public.bookings for select to authenticated using(public.is_goodfellas_admin());
drop policy if exists "Admins can update bookings" on public.bookings;create policy "Admins can update bookings" on public.bookings for update to authenticated using(public.is_goodfellas_admin()) with check(public.is_goodfellas_admin());
drop policy if exists "Admins can delete bookings" on public.bookings;create policy "Admins can delete bookings" on public.bookings for delete to authenticated using(public.is_goodfellas_admin());
drop policy if exists "Public can view active professionals" on public.professionals;create policy "Public can view active professionals" on public.professionals for select using(active=true or public.is_goodfellas_admin());
drop policy if exists "Admins manage professionals" on public.professionals;create policy "Admins manage professionals" on public.professionals for all to authenticated using(public.is_goodfellas_admin()) with check(public.is_goodfellas_admin());
drop policy if exists "Public can view active gallery" on public.gallery_photos;create policy "Public can view active gallery" on public.gallery_photos for select using(active=true or public.is_goodfellas_admin());
drop policy if exists "Admins manage gallery" on public.gallery_photos;create policy "Admins manage gallery" on public.gallery_photos for all to authenticated using(public.is_goodfellas_admin()) with check(public.is_goodfellas_admin());
drop policy if exists "Public can read shop settings" on public.shop_settings;create policy "Public can read shop settings" on public.shop_settings for select using(true);
drop policy if exists "Admins manage shop settings" on public.shop_settings;create policy "Admins manage shop settings" on public.shop_settings for all to authenticated using(public.is_goodfellas_admin()) with check(public.is_goodfellas_admin());
grant usage on schema public to anon,authenticated;grant select on public.services,public.professionals,public.gallery_photos,public.shop_settings to anon,authenticated;grant insert on public.bookings to anon,authenticated;grant select,update,delete on public.bookings to authenticated;grant insert,update,delete on public.services,public.professionals,public.gallery_photos,public.shop_settings to authenticated;grant select on public.admin_users to authenticated;
insert into public.services(name,description,duration_minutes,price_idr,sort_order) select * from(values('Classic Haircut','Potongan klasik, bersih, dan rapi.',30,45000,1),('Haircut + Wash','Potong rambut dilanjutkan hair wash.',40,55000,2),('Fade / Taper','Detail fade presisi dengan finishing clean.',40,55000,3),('Haircut + Styling','Potongan dan styling sesuai karakter.',45,65000,4),('Beard Trim','Rapikan kumis dan jenggot.',20,30000,5)) as v(name,description,duration_minutes,price_idr,sort_order) where not exists(select 1 from public.services);
insert into public.shop_settings(id,shop_name,address,instagram_url) values(1,'GOODFELLAS','Cirebon, Jawa Barat','https://www.instagram.com/goodfellas_cirebon/') on conflict(id) do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('goodfellas-gallery','goodfellas-gallery',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
drop policy if exists "Public can view Goodfellas gallery images" on storage.objects;create policy "Public can view Goodfellas gallery images" on storage.objects for select using(bucket_id='goodfellas-gallery');
drop policy if exists "Admins can upload Goodfellas gallery images" on storage.objects;create policy "Admins can upload Goodfellas gallery images" on storage.objects for insert to authenticated with check(bucket_id='goodfellas-gallery' and public.is_goodfellas_admin());
drop policy if exists "Admins can update Goodfellas gallery images" on storage.objects;create policy "Admins can update Goodfellas gallery images" on storage.objects for update to authenticated using(bucket_id='goodfellas-gallery' and public.is_goodfellas_admin()) with check(bucket_id='goodfellas-gallery' and public.is_goodfellas_admin());
drop policy if exists "Admins can delete Goodfellas gallery images" on storage.objects;create policy "Admins can delete Goodfellas gallery images" on storage.objects for delete to authenticated using(bucket_id='goodfellas-gallery' and public.is_goodfellas_admin());
create or replace function public.goodfellas_public_slots(p_date date,p_barber text default 'Barber tersedia') returns table(booking_time time,barber_name text) language sql stable security definer set search_path=public as $$ select b.booking_time,b.barber_name from public.bookings b where b.booking_date=p_date and b.status<>'cancelled' and(p_barber='Barber tersedia' or b.barber_name=p_barber); $$;
revoke all on function public.goodfellas_public_slots(date,text) from public;grant execute on function public.goodfellas_public_slots(date,text) to anon,authenticated;
create unique index if not exists goodfellas_unique_active_slot on public.bookings(booking_date,booking_time,barber_name) where status<>'cancelled';